use vstd::prelude::*;
use vstd::vec::*;

verus! {

pub fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i && i < a.len() ==> result[i] == a[i],
{
    let mut result = Vec::new();
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            result.len() == i,
            forall|j: int| 0 <= j && j < i ==> result[j] == a[j],
            i <= a.len(),
    {
        result.push(a[i]);
        i = i + 1;
    }
    
    result
}

#[verifier(external)]
fn main() {
    let v = vec![1, 2, 3, 4, 5];
    let copied = copy(&v);
    println!("Original: {:?}", v);
    println!("Copy: {:?}", copied);
    assert!(copied.len() == v.len());
    for i in 0..v.len() {
        assert!(copied[i] == v[i]);
    }
}

} // verus!